cat > checks/public.cjs <<'EOF'
const assert = require('node:assert/strict');
const { EventService } = require('../.build/service');

// Fixtures implement the Source/Lease contract from src/source.ts.
function fixture({ values = ['a', 'b', null], readError, closeError, mapper } = {}) {
  const calls = { opens: 0, reads: 0, closes: 0 };
  const source = {
    async open() {
      calls.opens++;
      return {
        async read() {
          calls.reads++;
          if (readError) throw readError;
          return values.shift();
        },
        async close() {
          calls.closes++;
          if (closeError) throw closeError;
        },
      };
    },
  };
  return { calls, stream: new EventService(source, mapper).stream() };
}

async function main() {
  const unopened = fixture();
  assert.deepEqual(unopened.calls, { opens: 0, reads: 0, closes: 0 });
  await unopened.stream.return();
  assert.deepEqual(unopened.calls, { opens: 0, reads: 0, closes: 0 });

  const ordered = fixture();
  assert.deepEqual(await ordered.stream.next(), { value: 'A', done: false });
  assert.deepEqual(ordered.calls, { opens: 1, reads: 1, closes: 0 });
  assert.deepEqual(await ordered.stream.next(), { value: 'B', done: false });
  assert.deepEqual(ordered.calls, { opens: 1, reads: 2, closes: 0 });
  assert.equal((await ordered.stream.next()).done, true);
  await ordered.stream.next();
  await ordered.stream.return();
  assert.deepEqual(ordered.calls, { opens: 1, reads: 3, closes: 1 });

  for (const closeError of [undefined, new Error('close')]) {
    for (const mode of ['exhaustion', 'return', 'break', 'read', 'mapper', 'throw']) {
      const original = new Error(mode);
      const test = fixture({
        closeError,
        readError: mode === 'read' ? original : undefined,
        mapper: mode === 'mapper' ? () => { throw original; } : undefined,
      });
      const run = async () => {
        if (mode === 'exhaustion' || mode === 'break') {
          const found = [];
          for await (const value of test.stream) {
            found.push(value);
            if (mode === 'break') break;
          }
          assert.deepEqual(found, mode === 'break' ? ['A'] : ['A', 'B']);
        } else {
          await test.stream.next();
          if (mode === 'return') await test.stream.return();
          if (mode === 'throw') await test.stream.throw(original);
        }
      };
      const primary = ['read', 'mapper', 'throw'].includes(mode);
      if (primary || closeError) {
        await assert.rejects(run(), error => error === (primary ? original : closeError));
      } else {
        await run();
      }
      await test.stream.next();
      await test.stream.return();
      assert.equal(test.calls.closes, 1, mode);
      assert.equal(test.calls.reads, mode === 'exhaustion' ? 3 : 1, mode);
    }
  }

  // Even a thrown undefined is an original exception, not an absent error.
  const injected = fixture({ closeError: new Error('close') });
  await injected.stream.next();
  await assert.rejects(injected.stream.throw(undefined), error => error === undefined);
  assert.equal(injected.calls.closes, 1);

  const openError = new Error('open');
  const failedOpen = new EventService({ open: async () => { throw openError; } }).stream();
  await assert.rejects(failedOpen.next(), error => error === openError);
}
module.exports = main();
EOF
